 actions.append({'ruleId':'p3r.action.visit_'+slug,'entityId':'p3r.social_link.'+slug,'labelZh':'和'+person+'对话 · '+label,'locationZh':location,'slot':slot,'slotCost':1,'moneyCost':0,'moneyIncome':0,'preconditions':[{'path':f'socialLinks.{slug}.rank','operator':'gte','value':1},{'path':f'socialLinks.{slug}.rank','operator':'lt','value':10},{'path':f'socialLinks.{slug}.relationshipState','operator':'eq','value':'normal'},{'path':'calendar.entitySlotAvailable','operator':'eq','value':True}],'onCompletedNormalVisit':{'rankDelta':1,'rankCap':10},'predictionModel':'rank_increment_if_visit_completed','affinityRequired':False,'personaArcanaRequired':False,'availabilityRuleIds':[c['ruleId'] for c in cal['cells'] if c['entityId'].endswith(slug)],'verificationStatus':'corroborated','evidenceRefs':['wiki_links','aqiu_calendar'],'calendarScope':'01-02..01-30 only','unmetPrecondition':'unknown_or_unavailable_do_not_infer_unlocked','localization':'original candidate descriptions, no inferred personal names'})
